/// <summary>
/// Controller class to triggers the batch execution to Update Stock availability details for the replenishment sites fetching information from the related parent site.
/// </summary>
internal final class METUpdateStockAvailabilityController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Triggers the batch execution to Update Stock availability details for the replenishment sites fetching information from the related parent site.
/// </summary>
/// <param name = "_args">Variable of type Args, holding the parameters from the calling menu option</param>
public static void main(Args _args)
{
    METUpdateStockAvailabilityController controller = METUpdateStockAvailabilityController::construct(_args);

    if (controller)
    {
        METUpdateStockAvailabilityContract contract =  controller.getDataContractObject() as METUpdateStockAvailabilityContract;

        if (_args.menuItemName() == menuItemActionStr(METUdpateStockAvailabilityController))
        {
            controller.showBatchTab(false);
        }

        contract.initFromArgs(_args);
        controller.startOperation();
    }
}

/// <summary>
/// Creates and initializes an instance of <c>METUpdateStockAvailabilityController</c> with the specified service context and execution mode.
/// </summary>
/// <param name="_args">The <c>Args</c> object containing parameters from the calling menu option.</param>
/// <param name="_sysOperationExecutionMode">The execution mode for the operation. Defaults to <c>Asynchronous</c>.</param>
/// <returns>
/// An instance of <c>METUpdateStockAvailabilityController</c> configured with the provided arguments and execution mode.
/// </returns>
public static SysOperationController construct(Args _args, SysOperationExecutionMode _sysOperationExecutionMode = SysOperationExecutionMode::Asynchronous)
{
    if (_args.record())
    {
        _sysOperationExecutionMode = SysOperationExecutionMode::Synchronous;
    }

    SysOperationController controller = new METUpdateStockAvailabilityController(classStr(METUpdateStockAvailabilityService),
        methodStr(METUpdateStockAvailabilityService, process),
        _sysOperationExecutionMode);

    controller.parmArgs(_args);
    controller.batchInfo().parmBatchExecute(_args.record() ? false : true);
    controller.parmLoadFromSysLastValue(false);

    return controller;
}

/// <summary>
/// Setting up the caption or title for the batch execution process and the dialog.
/// </summary>
/// <returns>String context as name for the batch execution and dialog</returns>
protected ClassDescription defaultCaption()
{
    return "@MET:UpdateStockAvailabilityDetails";
}
